python3 << 'EOF'
# I believe the table shows TOTAL outlays (on-budget + off-budget combined)
# Let me verify by checking if the total matches

# Based on table FFO-3, let's collect the data for FY 2012-2019
# We'll use the values from each year's final actual figure

import json
import re

def get_year_data(content, target_years):
    """Extract year -> (Agriculture, Energy) from table content"""
    rows = content.split('<tr>')
    result = {}

    for row in rows:
        # Match full fiscal year row: <td>201X</td> (not "2016 - Est" or "2015 - Sept")
        match = re.search(r'<td>(20\d{2})(?![\s\-])</td>', row)
        if match:
            year = match.group(1)
            if year in target_years:
                values = re.findall(r'<td>([\d,\-]+)</td>', row)
                if len(values) >= 8:
                    try:
                        # Index 3 = Agriculture, Index 7 = Energy
                        ag = int(values[3].replace(',', ''))
                        energy = int(values[7].replace(',', ''))
                        result[year] = {'Agriculture': ag, 'Energy': energy}
                    except:
                        pass
    return result

# Collect data from bulletins - prefer later bulletins for same years
target_years = ['2012', '2013', '2014', '2015', '2016', '2017', '2018', '2019']

# 2016 bulletin: has 2012-2016
with open('/app/resources/treasury_bulletin_2016_12.json') as f:
    d2016 = json.load(f)
for i, elem in enumerate(d2016['document']['elements']):
    if elem.get('type') == 'table':
        content = str(elem.get('content', ''))
        if 'Department of Energy' in content and 'Department of Agriculture' in content and '2012' in content:
            data_2012_2016 = get_year_data(content, target_years)
            print('2016 bulletin (2012-2016):', data_2012_2016)
            break

# 2017 bulletin: has 2013-2017
with open('/app/resources/treasury_bulletin_2017_12.json') as f:
    d2017 = json.load(f)
for i, elem in enumerate(d2017['document']['elements']):
    if elem.get('type') == 'table':
        content = str(elem.get('content', ''))
        if 'Department of Energy' in content and 'Department of Agriculture' in content and '2017' in content:
            data_2013_2017 = get_year_data(content, target_years)
            print('2017 bulletin (2013-2017):', data_2013_2017)
            break

# 2020 bulletin: has 2016-2019
with open('/app/resources/treasury_bulletin_2020_12.json') as f:
    d2020 = json.load(f)
for i, elem in enumerate(d2020['document']['elements']):
    if elem.get('type') == 'table':
        content = str(elem.get('content', ''))
        if 'Department of Energy' in content and 'Department of Agriculture' in content and '2018' in content:
            data_2016_2019 = get_year_data(content, target_years)
            print('2020 bulletin (2016-2019):', data_2016_2019)
            break

# Combine: prefer later bulletins
combined = {}
# Start with 2016 bulletin for 2012-2016
for year in ['2012', '2013', '2014', '2015', '2016']:
    combined[year] = data_2012_2016[year]
# Use 2017 bulletin for 2017 (not in 2016 bulletin)  
combined['2017'] = data_2013_2017['2017']
# Use 2020 bulletin for 2018-2019
for year in ['2018', '2019']:
    combined[year] = data_2016_2019[year]

print('\n=== FINAL Combined data for FY 2012-2019 ===')
for year in sorted(combined.keys()):
    print(f"{year}: Agriculture={combined[year]['Agriculture']}, Energy={combined[year]['Energy']}")
EOF
